def shape(unit, integration, ui):
    if unit == integration == ui == 0:
        return 'empty'
    if unit > integration > ui:
        return 'pyramid'
    if ui > integration > unit:
        return 'ice-cream cone'
    if unit > integration and ui > integration:
        return 'hourglass'
    if integration > unit and integration > ui:
        return 'diamond'
    return 'mixed'
